/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00600.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // showObj(MxGrid_1, false);
    // showObj(MxGrid_2, false);

    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_4);
    scwin.setCondTitle("신규저장");

    // 데이터셋 초기화
    scwin.initDs();

    // 기본값 세팅
    scwin.setDefaultVal();
};

