    try {
        if (dts_List.getRowCount() <= 0) {
            await $c.win.alert("조회된 데이터가 없습니다.");
            return;
        }
        $c.data.downloadGridViewExcel(grd_List, {fileName: "조건검색", type: "8"});
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600.btn_Excel_onclick" });
    }
};

