};

/**
 * @method
 * @name saveTemp
 * @description 임시저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTemp = async function() {
    // 저장용 데이터 세팅
    if (!await scwin.setSaveData()) {
        return false;
    }

    // 임시저장여부에따라 분기. 조건이 조건읽기 팝업에서 세팅된경우는 임시저장 하지 않는다.
    if (scwin.vTmpSave) {
        trs_save.KeyName = "toinb_dataid4";
        // trs_save.Parameters    = "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm;
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/ConditionSrchAction.do",
            ref : "dts_KeyInfo,dts_Fz530,dts_Fz531",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
    return true;
};

