/**
 * @method
 * @name setBeforeRadioBtn
 * @description 이전 라디오 버튼 정보 가져온다
 * @returns {void}
 * @hidden N
 */
scwin.setBeforeRadioBtn = function() {
    scwin.before_bas_btn = rdo_Bas.getValue();
    scwin.before_horiz_btn = rdo_Horiz.getValue();
    scwin.before_verti_btn = rdo_Verti.getValue();
};

/**
 * @method
 * @name getBeforeRadioBtn
 * @description 라디오버튼 정보를 등록
 * @param {*} rdo_btn rdo_btn
 * @returns {void}
 * @hidden N
 */
scwin.getBeforeRadioBtn = function(rdo_btn) {
    if (rdo_btn === "ALL") {
        rdo_Bas.setValue(scwin.before_bas_btn);
        rdo_Horiz.setValue(scwin.before_horiz_btn);
        rdo_Verti.setValue(scwin.before_verti_btn);
    } else if (rdo_btn === "rdo_Bas") {
        rdo_Bas.setValue(scwin.before_bas_btn);
    } else if (rdo_btn === "rdo_Horiz") {
        rdo_Horiz.setValue(scwin.before_horiz_btn);
    } else if (rdo_btn === "rdo_Verti") {
        rdo_Verti.setValue(scwin.before_verti_btn);
    }
};

