/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.clearDs();

    // 일단 조건을 저장하자. 화면에서 조건을 만들어 넘겼는데 세로항목이 많아지니까 화면에서 뻗어버린다.
    if (!await scwin.saveTemp()) {
        return;
    } else {
        await scwin.search2();
    }
};

/**
 * @method
 * @name setSaveData
 * @description 저장될 데이터를 세팅한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSaveData = async function() {
    // 저장전 체크.
    if (!await scwin.chkValid()) {
        return false;
    }

    // 저장용 데이터 세팅.
    dts_Fz530.removeAll();
    dts_Fz530.insertRow();
