/**
 * @method
 * @name getCondition
 * @description 조회조건 get방식의 문자열 만들기
 * @returns {void}
 * @hidden N
 */
scwin.getCondition = function() {
    let sCondition = "";
    sCondition = "&{P}IND_PTTN=" + cmb_IND_PTTN.getValue() + "&{P}FISCAL_TYP=" + cmb_FISCAL_TYP.getValue() + "&{P}INDVDL_CONN_TP=" + cmb_INDVDL_CONN_TP.getValue() + "&{P}ACNTG_BAS_TYP=" + cmb_ACNTG_BAS_TYP.getValue(); // G KGGAP, I IFRS

    // 기준, 가로, 세로 조건에 담기.
    let sVerti = "";
    let sBase = "";
    let nCntHoriz = 0;
    for (let nRow = 1; nRow <= dts_Fz531.getRowCount(); nRow++) {
        const AXIS_TYP = dts_Fz531.getCellData(nRow, "AXIS_TYP"); // 1 기준, 2 가로, 3 세로
        const ITEM_CD = dts_Fz531.getCellData(nRow, "ITEM_CD");

        // 기준
        if (AXIS_TYP === "1") {
            sCondition += "&{P}BASE=" + ITEM_CD;
        }
        // 가로
        else if (AXIS_TYP === "2") {
            let COL_YEAR = dts_Fz531.getCellData(nRow, "COL_YEAR");
            let FIELD_IDX = dts_Fz531.getCellData(nRow, "FIELD_IDX");
            if (COL_YEAR !== "0000") {
                sCondition += "&{P}HORIZ_YYYY" + FIELD_IDX + "=" + COL_YEAR;
                if (sBase.indexOf(COL_YEAR) === -1) {
                    sBase += ",'" + COL_YEAR + "'";
                }
            }
            sCondition += "&{P}HORIZ_" + FIELD_IDX + "=" + ITEM_CD;
            nCntHoriz = Number(FIELD_IDX);
        }
        // 세로
        else if (AXIS_TYP === "3") {
            let COL_YEAR = dts_Fz531.getCellData(nRow, "COL_YEAR");
            let FIELD_IDX = dts_Fz531.getCellData(nRow, "FIELD_IDX");
            if (COL_YEAR !== "0000") {
                if (sBase.indexOf(COL_YEAR) === -1) {
                    sBase += ",'" + COL_YEAR + "'";
                }
            }
        }
    }
    // sCondition += "&{P}VERTI=" + sVerti.substring(1);
    sCondition += "&{P}BASE_LIST=" + sBase.substring(1);
    sCondition += "&{P}TABLE_NM=" + scwin.getTableName();
    sCondition += "&{P}EMP_NO=" + dts_KeyInfo.getCellData(1, "EMP_NO");
    sCondition += "&{P}TYP=" + dts_KeyInfo.getCellData(1, "TYP");
    sCondition += "&{P}GUBUN=" + dts_KeyInfo.getCellData(1, "GUBUN");
    sCondition += "&{P}SEQ_NO=" + dts_KeyInfo.getCellData(1, "SEQ_NO");

    // 파라미터가 없으면 에러나기때문에 강제로 만들자.
    for (nCntHoriz++; nCntHoriz < scwin.vHorizLimitCnt; nCntHoriz++) {
        sCondition += "&{P}HORIZ_" + nCntHoriz + "=";
        sCondition += "&{P}HORIZ_YYYY" + nCntHoriz + "=";
    }
    return sCondition;
};

/**
 * @method
 * @name getTableName
 * @description 조건에따라 테이블이름 구하기. TB_FN_FE110    개별 KGGAP TB_FN_FE120    개별 IFRS TB_FN_FE310    연결 KGGAP TB_FN_FE320    연결 IFRS
 * @returns {void}
 * @hidden N
 */
scwin.getTableName = function() {
    let sTableNm = "";
    const sIndvdlConnTp = cmb_INDVDL_CONN_TP.getValue(); // 1 개별, 2 연결
    const sAcntgBasTyp = cmb_ACNTG_BAS_TYP.getValue(); // G KGGAP, I IFRS

    if (sIndvdlConnTp === "1" && sAcntgBasTyp === "G") {
        sTableNm = "TB_FN_FE110";
    } else if (sIndvdlConnTp === "1" && sAcntgBasTyp === "I") {
        sTableNm = "TB_FN_FE120";
    } else if (sIndvdlConnTp === "2" && sAcntgBasTyp === "G") {
        sTableNm = "TB_FN_FE310";
    } else if (sIndvdlConnTp === "2" && sAcntgBasTyp === "I") {
        sTableNm = "TB_FN_FE320";
    }
    return sTableNm;
};

/**
 * @method
 * @name getQueryId
 * @description 조회유형에따른 queryId 구하기.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getQueryId = async function() {
    let vQueryId = "";

    // AXIS_TYP  1 기준, 2 가로축, 3 세로축
    let nTmpIdx1 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "1");
    let nTmpIdx2 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "2");
    let nTmpIdx3 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "3");

    // 기준이 존재하면 (A, B, C) 유형임.
    if (nTmpIdx1 >= 1) {
        const ITEM_TYP1 = dts_Fz531.getCellData(nTmpIdx1, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사
        const ITEM_TYP2 = dts_Fz531.getCellData(nTmpIdx2, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사

        // A타입
        if (ITEM_TYP1 === "0") {
            if (ITEM_TYP2 === "3") {
                vQueryId = "krx.lds.stf.fis.select.condSrchA1";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchA2";
            }
            // C 타입

        } else if (ITEM_TYP1 === "1") {
            if (ITEM_TYP2 === "0") {
                vQueryId = "krx.lds.stf.fis.select.condSrchC1";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchC2";
            }
            // B 타입

        } else if (ITEM_TYP1 === "3") {
            if (ITEM_TYP2 === "0") {
                vQueryId = "krx.lds.stf.fis.select.condSrchB1";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchB2";
            }
        }
        // D 타입(년도가 가로에 붙었냐? 세로에 붙었냐??)

    } else {
        // 년도가 가로에 붙었는지 세로에 붙었는지 확인.
        // 가로에 붙었다.
        if (dts_Fz531.getCellData(nTmpIdx2, "COL_YEAR") !== "0000") {
            let ITEM_TYP = dts_Fz531.getCellData(nTmpIdx2, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사
            if (ITEM_TYP === "1") {
                vQueryId = "krx.lds.stf.fis.select.condSrchD1";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchD2";
            }
        }
        // 세로에 붙었다.
        else if (dts_Fz531.getCellData(nTmpIdx3, "COL_YEAR") !== "0000") {
            let ITEM_TYP = dts_Fz531.getCellData(nTmpIdx3, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사
            if (ITEM_TYP === "3") {
                vQueryId = "krx.lds.stf.fis.select.condSrchD3";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchD4";
            }
        } else {
            await $c.win.alert("쿼리ID를 찾을 수 없습니다.");
            return "";
        }
    }
    return vQueryId;
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function() {
    // 가로, 세로 항목은 필수. AXIS_TYP 1/기준, 2/가로축, 3/세로축
    let nTmpIdx1 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "1");
    let nTmpIdx2 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "2");
    let nTmpIdx3 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "3");
    const COL_YEAR1 = dts_Fz531.getCellData(nTmpIdx2, "COL_YEAR");
    const COL_YEAR2 = dts_Fz531.getCellData(nTmpIdx3, "COL_YEAR");
    if (nTmpIdx2 < 1) {
        await $c.win.alert("가로항목을 선택하세요.");
        return false;
    }
    if (nTmpIdx3 < 1) {
        await $c.win.alert("세로항목을 선택하세요.");
        return false;
    }
    // 기준이 없다면 가로항목의 데이터조회기준년도가 체크되어 있으면 됨. 즉  COL_YEAR 값이 0000이 아님.
    if (nTmpIdx1 < 1) {
        if (COL_YEAR1 === "0000" && COL_YEAR2 === "0000") {
            await $c.win.alert("기준을 지정하세요.");
            return false;
        }
    }
    return true;
};

