/**
 * @method
 * @name setAxisInfo
 * @description 각 축정보 세팅
 * @param {*} pArr pArr
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAxisInfo = async function(pArr) {
    scwin.setBeforeRadioBtn();
    await scwin.setDtsFz531(pArr);
};

/**
 * @method
 * @name setDtsFz531
 * @description 기준, 가로, 세로 항목 정보를  DtsFz531 에 세팅. pAxisTyp : 1/기준, 2/가로축, 3/세로축
 * @param {*} pArr pArr
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDtsFz531 = async function(pArr) {
    // 임시저장여부 세팅
    scwin.vTmpSave = true;

    // 세팅전 각 축 정보를 삭제.
    scwin.initAxisInfo(pArr[0].AXIS_TYP);

    // 가로인 경우
    if (pArr[0].AXIS_TYP === "2") {
        if (pArr.length < 10) {
            $c.cm.setColumnProp(grd_List, "NAME", "width", 118 + (111 * 1));
        } else {
            $c.cm.setColumnProp(grd_List, "NAME", "width", 118);
        }
    }

    // 데이터조회기준년도 체크 시 기준지정은 비활성.
    if ((pArr[0].AXIS_TYP === "2" || pArr[0].AXIS_TYP === "3") && pArr[0].COL_YEAR !== "0000") {
        rdo_Bas.setValue("");
        rdo_Bas.setDisabled(true);
        rdo_Bas.Reset();
        await $c.win.alert("데이터조회기준년도 체크 시 기준지정은 비활성됩니다");
    } else {
        rdo_Bas.setDisabled(false);
        rdo_Bas.Reset();
    }
    dts_Fz531.setBroadcast(false);
    for (let nIdx = 0; nIdx < pArr.length; nIdx++) {
        dts_Fz531.insertRow();
        let nRow = dts_Fz531.getRowPosition();
        dts_Fz531.setCellData(nRow, "EMP_NO", js_emp_no);
        dts_Fz531.setCellData(nRow, "COND_TYP", "1");
        dts_Fz531.setCellData(nRow, "COND_GUBUN", "1");
        dts_Fz531.setCellData(nRow, "AXIS_TYP", pArr[nIdx].AXIS_TYP);
        dts_Fz531.setCellData(nRow, "ITEM_CD", pArr[nIdx].ITEM_CD);
        dts_Fz531.setCellData(nRow, "ITEM_TYP", pArr[nIdx].ITEM_TYP);
        dts_Fz531.setCellData(nRow, "ITEM_NM", pArr[nIdx].ITEM_NM);
        dts_Fz531.setCellData(nRow, "COL_YEAR", pArr[nIdx].COL_YEAR);
        dts_Fz531.setCellData(nRow, "ACCNT_EXP_TYP", "0"); // 0 일반
        dts_Fz531.setCellData(nRow, "FIELD_IDX", nIdx);
        dts_Fz531.setCellData(nRow, "USE_YN", "Y");
        dts_Fz531.setCellData(nRow, "SAVE_YN", "Y");
    }
    dts_Fz531.setBroadcast(true, true);

    // 그리드 타이틀 세팅. 매번 새로 세팅함.
    // fn_SetGrdTitle(vAxisType);
    scwin.setGrdTitle("9");
};

/**
 * @method
 * @name setGrdTitle
 * @description 그리드 타이틀 세팅. AXIS_TYP : 1/기준, 2/가로, 3/세로
 * @param {*} pGubun pGubun
 * @returns {void}
 * @hidden N
 */
scwin.setGrdTitle = function(pGubun) {
    if (pGubun === "1") {
        scwin.setGrdTitleBase();
    } else if (pGubun === "2") {
        scwin.setGrdTitleHoriz();
    } else if (pGubun === "3") {
        scwin.setGrdTitleVerti();
    } else {
        scwin.setGrdTitleBase();
        scwin.setGrdTitleHoriz();
        scwin.setGrdTitleVerti();
    }
};

/**
 * @method
 * @name setGrdTitleBase
 * @description 그리드 타이틀 세팅_기준 AXIS_TYP : 1/기준, 2/가로, 3/세로
 * @returns {void}
 * @hidden N
 */
scwin.setGrdTitleBase = function() {
    // txb_Year.value = pVal;
    // txb_Com.value = pVal;
    // txb_Accnt.value = pVal;
    // fn_InitGrid(1);
    let nRow = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "1");
    if (nRow >= 1) {
        $c.cm.setColumnProp(grd_List, "NAME", "Name", "기준:" + $c.stf.trim(dts_Fz531.getCellData(nRow, "ITEM_NM")));
    } else {
        $c.cm.setColumnProp(grd_List, "NAME", "Name", "");
    }
};

/**
 * @method
 * @name setGrdTitleHoriz
 * @description 그리드 타이틀 세팅_가로 AXIS_TYP : 1/기준, 2/가로, 3/세로
 * @returns {void}
 * @hidden N
 */
scwin.setGrdTitleHoriz = function() {
    // 그리드 초기화
    scwin.initGrid("2");
    let nIdx = 1;
    let nRow = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "2");
    for (; nRow <= dts_Fz531.getRowCount(); nRow++) {
        // 가로 세팅  1/기준, 2/가로, 3/세로
        if (dts_Fz531.getCellData(nRow, "AXIS_TYP") !== "2") {
            break;
        }
        $c.cm.setColumnProp(grd_List, "ACCNT_VAL" + nIdx, "Name", $c.stf.trim(dts_Fz531.getCellData(nRow, "ITEM_NM")));
        $c.cm.setColumnProp(grd_List, "ACCNT_VAL" + nIdx, "Show", true);
        nIdx++;
    }

    // 넓이 세팅
    if (nIdx < 11) {
        $c.cm.setColumnProp(grd_List, "NAME", "width", 118 + (111 * 1));
    } else {
        $c.cm.setColumnProp(grd_List, "NAME", "width", 118);
    }
    // fn_SetGridWidth();

};

/**
 * @method
 * @name setGrdTitleVerti
 * @description 그리드 타이틀 세팅_세로 AXIS_TYP : 1/기준, 2/가로, 3/세로
 * @returns {void}
 * @hidden N
 */
scwin.setGrdTitleVerti = function() {
    // 그리드 초기화
    scwin.initGrid("3");
    grd_List.ReDraw = false;
    let nIdx = 1;
    let nRow = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "3");
    dts_List.setBroadcast(false);
    for (; nRow <= dts_Fz531.getRowCount(); nRow++) {
        // 세로 세팅
        if (dts_Fz531.getCellData(nRow, "AXIS_TYP") !== "3") {
            break;
        }
        dts_List.insertRow();
        dts_List.setCellData(dts_List.getRowPosition(), "NAME", dts_Fz531.getCellData(nRow, "ITEM_NM"));
        nIdx++;
    }
    dts_List.setBroadcast(true, true);
    grd_List.ReDraw = true;
};

/**
 * @method
 * @name reset
 * @description 조회조건 초기화
 * @returns {void}
 * @hidden N
 */
scwin.reset = function() {
    dts_KeyInfo.removeAll();
    dts_Fz531.removeAll();
    dts_Fz530.removeAll();
    txb_conditionTitle.setValue("");
    scwin.setCondTitle("신규저장");
    rdo_Bas.setValue("");
    rdo_Horiz.setValue("");
    rdo_Verti.setValue("");
    rdo_Bas.setDisabled(false);
    rdo_Bas.Reset();
    rdo_Bas.focus();

    // 전역변수 초기화
    scwin.vAxisType = "";
    scwin.vTmpSave = true;
    scwin.before_bas_btn = 0;
    scwin.before_horiz_btn = 0;
    scwin.before_verti_btn = 0;
    scwin.cond_nm = "";
    scwin.cond_con = "";

    // 그리드 초기화
    scwin.initGrid("9");
};

/**
 * @method
 * @name initGrid
 * @description 그리드 초기화 pGubun :1 기준초기화, 2 가로초기화, 3 세로초기화
 * @param {*} pGubun pGubun
 * @returns {void}
 * @hidden N
 */
scwin.initGrid = function(pGubun) {
    if (pGubun === "9" || pGubun === "1") {
        // 기준초기화
        $c.cm.setColumnProp(grd_List, "NAME", "Name", "");
    }
    if (pGubun === "9" || pGubun === "2") {
        // 가로 초기화
        for (let nIdx = 1; nIdx < grd_List.getTotalCol(); nIdx++) {
            $c.cm.setColumnProp(grd_List, "ACCNT_VAL" + nIdx, "Show", false);
        }
    }
    if (pGubun === "9" || pGubun === "3") {
        // 세로 초기화
        dts_List.removeAll();
    }
};

/**
 * @method
 * @name initAxisInfo
 * @description dts_Fz531 초기화 pGubun :1 기준초기화, 2 가로초기화, 3 세로초기화, 9 모두 초기화
 * @param {*} pGubun pGubun
 * @returns {void}
 * @hidden N
 */
scwin.initAxisInfo = function(pGubun) {
    if (pGubun === "1" || pGubun === "2" || pGubun === "3") {
        dts_Fz531.setBroadcast(false);
        for (let nRow = dts_Fz531.getRowCount(); nRow >= 1; nRow--) {
            if (pGubun === dts_Fz531.getCellData(nRow, "AXIS_TYP")) {
                dts_Fz531.removeRow(nRow);
            }
        }
        dts_Fz531.setBroadcast(true, true);
    }
    if (pGubun === "9") {
        dts_Fz531.removeAll();
    }
    // 열의 상태를 nomal 로 변경.
    dts_Fz531.ResetStatus();
};

/**
 * @method
 * @name isSelectYear
 * @description dts_Fz531 의 데이터로 연도가 선택가능한지를 리턴한다. return: true 선택가능, false 선택불가 가로항목선택 시 기업, 계정코드 팝업창에서 데이터조회기준년도를 체크 한경우는 연도를 선택 할 수 없다.
 * @returns {void}
 * @hidden N
 */
scwin.isSelectYear = function() {
    let bSelect = true;

    // 가로항목 선택한 것이 있는가?
    let nRow = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "2");
    if (nRow >= 1) {
        // 있다면 COL_YEAR 값을 체크
        let COL_YEAR = dts_Fz531.getCellData(nRow, "COL_YEAR");
        if (COL_YEAR !== "0000") {
            bSelect = false;
        }
    }
    return bSelect;
};

/**
 * @method
 * @name setCondition
 * @description 조건읽기에서 호출됨. 조건 세팅
 * @param {*} pDataset pDataset
 * @param {*} pCondition pCondition
 * @returns {void}
 * @hidden N
 */
scwin.setCondition = function(pDataset, pCondition) {
    dts_Fz531.removeAll();
    $c.stf.copyDataSet(pDataset, dts_Fz531, "copyHeader=no");
    dts_KeyInfo.removeAll();
    dts_KeyInfo.insertRow();
    dts_KeyInfo.setCellData(1, "EMP_NO", pDataset.getCellData(1, "EMP_NO"));
    dts_KeyInfo.setCellData(1, "TYP", pDataset.getCellData(1, "COND_TYP"));
    dts_KeyInfo.setCellData(1, "GUBUN", pDataset.getCellData(1, "COND_GUBUN"));
    dts_KeyInfo.setCellData(1, "SEQ_NO", pDataset.getCellData(1, "COND_SEQ"));

    // 조회조건을 화면에 세팅.
    const aCond = pCondition.split("|");
    let aCondPair;
    for (let i = 0; i < aCond.length; i++) {
        aCondPair = $c.stf.trim(aCond[i]).split("=");
        if (aCondPair[0] === "rdo_Bas") {
            rdo_Bas.setValue(aCondPair[1]);
        } else if (aCondPair[0] === "rdo_Horiz") {
            rdo_Horiz.setValue(aCondPair[1]);
        } else if (aCondPair[0] === "rdo_Verti") {
            rdo_Verti.setValue(aCondPair[1]);
        } else if (aCondPair[0] === "cmb_IND_PTTN") {
            // rdo_Verti.CodeValue = aCondPair[1];

        } else {
            $p.getComponentById(aCondPair[0]).setValue(aCondPair[1]);
        }
    }

    // 기준 축이 없으면 기준지정 비활성.
    let nTmpIdx1 = pDataset.NameValueRow("AXIS_TYP", "1");
    if (nTmpIdx1 < 1) {
        rdo_Bas.setValue("");
        rdo_Bas.setDisabled(true);
        rdo_Bas.Reset();
    } else {
        rdo_Bas.setDisabled(false);
        rdo_Bas.Reset();
    }

    // 그리드 타이틀 세팅.
    scwin.setGrdTitle("9");

    // 임시저장여부 세팅
    scwin.vTmpSave = false;

    // 이전버튼 세팅
    scwin.setBeforeRadioBtn();

    // 자동조회
    // fn_search();

};

/**
 * @method
 * @name saveCondition
 * @description 조건저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveCondition = async function() {
    if (rdo_Bas.getValue() === "" || rdo_Horiz.getValue() === "" || rdo_Verti.getValue() === "") {
        await $c.win.alert("항목을 선택하세요");
        return false;
    }

    // 일단 조건을 저장하자. 화면에서 조건을 만들어 넘겼는데 세로항목이 많아지니까 화면에서 뻗어버린다.
    if (!await scwin.saveTemp()) {
        return false;
    }

    // var arrPos = getLeftTopPos(image_1);
    let arrPos = $c.stf.getLeftTopPos(label_9);
    const options = {
        id: "ULDFIS00600_P8",
        title: "조건저장",
        type: "browserPopup",
        width: 525 + 20,
        height: 205 + 40,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("./ULDFIS00600_P8.gfm", options);
};

/**
 * @method
 * @name getConditionString
 * @description 조건을 스트링으로 만들기
 * @returns {void}
 * @hidden N
 */
scwin.getConditionString = function() {
    let tmpStr = "";
    tmpStr += "cmb_IND_PTTN=" + cmb_IND_PTTN.getValue();
    tmpStr += "|cmb_FISCAL_TYP=" + cmb_FISCAL_TYP.getValue();
    tmpStr += "|cmb_INDVDL_CONN_TP=" + cmb_INDVDL_CONN_TP.getValue();
    tmpStr += "|cmb_ACNTG_BAS_TYP=" + cmb_ACNTG_BAS_TYP.getValue();
    tmpStr += "|rdo_Bas=" + rdo_Bas.getValue();
    tmpStr += "|rdo_Horiz=" + rdo_Horiz.getValue();
    tmpStr += "|rdo_Verti=" + rdo_Verti.getValue();
    return tmpStr;
};

/**
 * @method
 * @name setGridWidth
 * @description 조건을 스트링으로 만들기
 * @returns {void}
 * @hidden N
 */
scwin.setGridWidth = function() {
    // 보이는 컬럼 갯수 구하기.
    let nShowCnt = 0;
    for (let nIdx = 1; nIdx < grd_List.getTotalCol(); nIdx++) {
        // grd_List.ColumnProp("ACCNT_VAL"+nIdx, "Name") = dts_Fz531.NameString(nRow, "ITEM_NM");
        if ($c.cm.getColumnProp(grd_List, grd_List.getColumnID(nIdx), "Show") === "TRUE") {
            nShowCnt++;
        }
    }
    const nWidth = (1245 - 17 - 118) / nShowCnt; // (총크기 - 스크롤크기 - 첫번째컬럼크기)/보이는컬럼갯수
    for (let nIdx = 1; nIdx < grd_List.getTotalCol(); nIdx++) {
        if ($c.cm.getColumnProp(grd_List, grd_List.getColumnID(nIdx), "Show") === "TRUE") {
            $c.cm.setColumnProp(grd_List, grd_List.getColumnID(nIdx, nWidth), "width", '');
        }
    }
};
